arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2010_12.json', 'r') as f:
    data = json.load(f)
# Find keys in the JSON
if isinstance(data, dict):
    print('Top level keys:', list(data.keys())[:10])
    for k in list(data.keys())[:3]:
        if isinstance(data[k], dict):
            print(f'  {k} keys:', list(data[k].keys())[:10])
elif isinstance(data, list):
    print('Is a list with', len(data), 'items')
    if len(data) > 0:
        print('First item keys:', list(data[0].keys())[:10] if isinstance(data[0], dict) else data[0])
"
